const panel=$('#panel');
const external=(url,text)=>`<a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`;
function projectMarkup(p,i){return `<article class="artifact"><div class="artifact-top"><span class="artifact-index">${String(i+1).padStart(2,'0')}</span><button class="artifact-title" aria-expanded="false" aria-controls="details-${p.id}">${p.title}<span aria-hidden="true">+</span></button></div><p class="artifact-summary">${p.summary}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="artifact-details" id="details-${p.id}" hidden><ul>${p.details.map(t=>`<li>${t}</li>`).join('')}</ul>${p.link?external(p.link,p.linkText):'<p>Documented in the CV. A dedicated project link has not been supplied.</p>'}</div></article>`;}
function renderProjects(){const shown=projects.filter(p=>filter==='all'||p.kind===filter);$('#projects').innerHTML=shown.map(p=>projectMarkup(p,projects.indexOf(p))).join('');document.querySelectorAll('.artifact-title').forEach(b=>b.addEventListener('click',()=>{const isOpen=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!isOpen));b.lastElementChild.textContent=isOpen?'+':'−';document.getElementById(b.getAttribute('aria-controls')).hidden=isOpen;}));}
function body(content){return `<div class="panel-body">${content}</div>`;}
function openPanel(type){if(!panel.open)lastFocus=document.activeElement;currentPanel=type;$('#panel-number').textContent={archive:'THE COLLECTED WORKS / 01',keeper:'THE KEEPER / 02',letter:'CORRESPONDENCE / 03',guide:'A SMALL FIELD GUIDE'}[type];
if(type==='archive'){$('#panel-content').innerHTML=body(`<p class="eyebrow">SEVEN THINGS THAT TOOK ROOT</p><h2 id="panel-title">The collected<br><em>works.</em></h2><p class="panel-lead">Observations, connections, and small acts of engineering. Every branch leads somewhere.</p><div class="filters" role="group" aria-label="Filter projects"><button class="filter active" data-filter="all" aria-pressed="true">All artifacts <small>07</small></button><button class="filter" data-filter="data" aria-pressed="false">Data engineering</button><button class="filter" data-filter="software" aria-pressed="false">Software engineering</button></div><div id="projects" aria-live="polite"></div><p class="archive-note">Collected from Tendai’s data engineering and software engineering CVs. Open an artifact to read its story.</p>`);filter='all';renderProjects();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderProjects();}));}
if(type==='keeper'){$('#panel-content').innerHTML=body(`<p class="eyebrow">A NOTE LEFT IN THE ROOTS</p><h2 id="panel-title">Meet the<br><em>keeper.</em></h2><p class="panel-lead">I’m interested in the things beneath the surface. The pipeline behind the picture. The logic behind the experience.</p><p class="archive-note">A small introduction, written for this archive.</p><p class="keeper-signature">Tendai Moross Sakadza</p><p class="keeper-role">SOFTWARE & DATA ENGINEERING · JOHANNESBURG</p><p style="font-size:13px;line-height:1.9;color:var(--muted)">Computer Science and Informatics graduate from the University of Johannesburg. I build data pipelines, automated systems, and applications that connect useful ideas to the people who need them.</p><div>${external('https://github.com/Salista-glitch','GitHub')}${external('https://www.linkedin.com/in/tendaisakadza/','LinkedIn')}</div><div class="chapter"><h3>Two ways into the work</h3><p>Data engineering: Python, SQL, pandas, Prefect, dbt, BigQuery, Google Cloud Storage, PostgreSQL, and SQLite.</p><p>Software engineering: Java, JavaScript, C#, React, React Native, Node.js, Express.js, ASP.NET, MySQL, and Docker.</p><div class="cv-links"><a href="assets/Tendai-Sakadza-Data-Engineering.pdf" download>Data engineering CV ↓<small>THE PIPELINES & THE PATTERNS · PDF</small></a><a href="assets/Tendai-Sakadza-Software-Engineering.pdf" download>Software engineering CV ↓<small>THE SYSTEMS & THE EXPERIENCES · PDF</small></a></div></div><div class="chapter"><h3>Places I’ve put down roots</h3><div class="timeline-item"><strong>Tech Associate · African Montessori Hub</strong><small>CONTRACTOR · FEB — DEC 2025</small><p>Built the nonprofit’s public-facing website, supporting educators and caregivers across Africa.</p>${external('https://www.africanmontessorihub.org/','Visit African Montessori Hub')}</div><div class="timeline-item"><strong>Informatics II Teaching Assistant · UJ</strong><small>FEB — NOV 2025</small><p>Supported software engineering labs and tutorials, reviewed assignments, and offered feedback on project structure and maintainability.</p></div></div><div class="chapter"><h3>A few things earned along the way</h3><p>BSc, Computer Science and Informatics · University of Johannesburg · 2023–2025</p><ul><li>UJenius · Academic Top 1% (2024)</li><li>Top 10 First Year Achievers Academic Award (2023)</li><li>UJenius Bursary · 100% internal merit scholarship (2024)</li></ul></div>`);}
if(type==='letter'){$('#panel-content').innerHTML=body(`<p class="eyebrow">SOME THINGS BEGIN WITH A HELLO</p><h2 id="panel-title">An unwritten<br><em>letter.</em></h2><p class="panel-lead">A curious idea? A role worth exploring? Or perhaps you simply found your way here.</p><a class="mail-address" href="mailto:tendai.sakadza@gmail.com">tendai.sakadza@gmail.com ↗</a><form class="letter-form" id="letter-form"><label for="sender">YOUR NAME</label><input id="sender" name="sender" autocomplete="name" placeholder="A fellow wanderer" maxlength="120" required><label for="reply">YOUR EMAIL</label><input id="reply" name="reply" type="email" autocomplete="email" placeholder="Somewhere I can write back" maxlength="200" required><label for="message">YOUR LETTER</label><textarea id="message" name="message" placeholder="Dear Tendai…" maxlength="5000" required></textarea><button class="seal" type="submit">Open your letter in email ↗</button><p class="form-note">Opens a draft in your email app, addressed to Tendai. You choose when to send it. Your letter is never stored by this website.</p><p class="form-note" id="letter-status" role="status"></p></form>`);$('#letter-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const subject=`A letter from ${f.get('sender')} · The Scarlet Archive`;const message=`Dear Tendai,\n\n${f.get('message')}\n\n${f.get('sender')}\nReply to: ${f.get('reply')}`;window.location.href=`mailto:tendai.sakadza@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`;$('#letter-status').textContent='Your email app has been invited to open the draft. If it doesn’t open, use the email address above.';});}
if(type==='guide'){$('#panel-content').innerHTML=body(`<p class="eyebrow">FOR THOSE WHO WANDER</p><h2 id="panel-title">A small<br><em>field guide.</em></h2><p class="panel-lead">You are not lost. Probably.</p><div class="guide-row"><b>01</b><div><h3>Follow the markers</h3><p>The three numbered points on the tree hold collected works, a note from the keeper, and a place to write. The navigation above leads to the same places.</p></div></div><div class="guide-row"><b>02</b><div><h3>Catch what falls upward</h3><p>There’s a wandering scarlet leaf near the tree. Touch it. It has a few things to say. The laws of gravity were never formally approved here.</p></div></div><div class="guide-row"><b>03</b><div><h3>Settle into the silence</h3><p>Sound is optional. Switch it on for a quiet, generative atmosphere. Choose Stillness below to let the world rest.</p></div></div><div class="guide-row"><b>↗</b><div><h3>Leave whenever you like</h3><p>Use Return to the tree, press Escape, or click outside this page. Every marker and artifact can also be explored with your keyboard.</p></div></div>`);}
if(!panel.open)panel.showModal();$('#scrim').classList.add('visible');panel.scrollTop=0;$('#close').focus();}
function closePanel(){if(!panel.open)return;panel.close();$('#scrim').classList.remove('visible');currentPanel='';lastFocus?.focus();}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.panel)));
$('#close').addEventListener('click',closePanel);$('#scrim').addEventListener('click',closePanel);panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)closePanel();}});$('.brand').addEventListener('click',closePanel);
let still=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{const saved=localStorage.getItem('scarlet-still');if(saved!==null)still=saved==='true';}catch{}
function setStill(){document.body.classList.toggle('still',still);$('#motion').setAttribute('aria-pressed',String(still));$('#motion').innerHTML=`STILLNESS <span>${still?'●':'○'}</span>`;if(still){ctx.clearRect(0,0,cw,ch);}else{lastTime=performance.now();requestAnimationFrame(animate);}}
$('#motion').addEventListener('click',()=>{still=!still;try{localStorage.setItem('scarlet-still',String(still));}catch{}setStill();});
let audioCtx=null,master=null,soundOn=false,soundNodes=[];
$('#sound').addEventListener('click',async()=>{try{if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=0;master.connect(audioCtx.destination);[130.81,196,261.63,293.66].forEach((freq,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.045/(i+1);o.connect(g);g.connect(master);o.start();soundNodes.push(o);});const len=audioCtx.sampleRate*4,b=audioCtx.createBuffer(1,len,audioCtx.sampleRate),d=b.getChannelData(0);let previous=0;for(let i=0;i<len;i++){previous=(previous+.025*(Math.random()*2-1))/1.025;d[i]=previous*2;}const source=audioCtx.createBufferSource();source.buffer=b;source.loop=true;const low=audioCtx.createBiquadFilter();low.type='lowpass';low.frequency.value=500;source.connect(low);const gain=audioCtx.createGain();gain.gain.value=.1;low.connect(gain);gain.connect(master);source.start();soundNodes.push(source);}await audioCtx.resume();soundOn=!soundOn;master.gain.setTargetAtTime(soundOn?.45:0,audioCtx.currentTime,.8);$('#sound').setAttribute('aria-pressed',String(soundOn));$('#sound').setAttribute('aria-label',soundOn?'Mute ambient sound':'Enable ambient sound');$('.sound-label').textContent=soundOn?'SOUND ON':'SOUND OFF';}catch{$('.sound-label').textContent='UNAVAILABLE';$('#sound').setAttribute('aria-label','Ambient sound unavailable in this browser');}});
document.addEventListener('visibilitychange',()=>{if(audioCtx){if(document.hidden)audioCtx.suspend();else if(soundOn)audioCtx.resume();}});
const whispers=['The tree is older than the idea of a deadline.','Gravity is more of a suggestion here.','Every good system begins with a small curiosity.','The archive remembers. Even the first draft.','You found this leaf. It insists it found you.'];let leafCount=0,whisperTimeout;
$('#stray').addEventListener('click',()=>{const w=$('#whisper');w.textContent=whispers[leafCount++%whispers.length];w.classList.add('visible');clearTimeout(whisperTimeout);whisperTimeout=setTimeout(()=>w.classList.remove('visible'),6500);if(!still){for(let i=0;i<25;i++)particles.push({x:cw*.35,y:ch*.5,vx:(Math.random()-.5)*1.5,vy:-.3-Math.random(),a:1,r:Math.random()*2+1});}});
const canvas=$('#leaves'),ctx=canvas.getContext('2d');let cw=1,ch=1,lastTime=0;const particles=[];const leaves=Array.from({length:24},()=>({x:Math.random(),y:.3+Math.random()*.6,size:2+Math.random()*4,speed:.005+Math.random()*.012,phase:Math.random()*6.28,spin:Math.random()*6.28}));
function resize(){const r=canvas.getBoundingClientRect();cw=r.width;ch=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}new ResizeObserver(resize).observe(canvas);resize();
function drawLeaf(x,y,size,angle,alpha){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.globalAlpha=alpha;ctx.fillStyle='#aa2533';ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.25,-size*.25);ctx.lineTo(size*.8,-size*.6);ctx.lineTo(size*.5,0);ctx.lineTo(size,.2*size);ctx.lineTo(size*.2,size*.4);ctx.lineTo(0,size);ctx.lineTo(-size*.2,size*.4);ctx.lineTo(-size,.2*size);ctx.lineTo(-size*.5,0);ctx.lineTo(-size*.8,-size*.6);ctx.lineTo(-size*.25,-size*.25);ctx.closePath();ctx.fill();ctx.restore();}
function animate(t){if(still)return;const dt=Math.min((t-lastTime)/1000,.05);lastTime=t;ctx.clearRect(0,0,cw,ch);leaves.forEach(l=>{l.y-=l.speed*dt;l.phase+=dt*.5;l.spin+=dt*.5;if(l.y<.12){l.y=.65+Math.random()*.28;l.x=.2+Math.random()*.65;for(let i=0;i<3;i++)particles.push({x:l.x*cw,y:ch*.12,vx:(Math.random()-.5)*.3,vy:-Math.random()*.3,a:.6,r:1});}const alpha=Math.min(1,Math.max(0,(l.y-.12)*4))*.65;drawLeaf(l.x*cw+Math.sin(l.phase)*16,l.y*ch,l.size,l.spin,alpha);});for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.a-=dt*.3;ctx.globalAlpha=Math.max(0,p.a);ctx.fillStyle='#b68c52';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();if(p.a<=0)particles.splice(i,1);}ctx.globalAlpha=1;requestAnimationFrame(animate);}setStill();
